/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AudioTrackStatus =
  | 'APPROVED'
  | 'FAILED'
  | 'GENERATING'
  | 'READY';

/** CEFR levels. An editorial estimate of a lesson's difficulty, not a guarantee of a learner's level. */
export type CefrLevel =
  | 'A1'
  | 'A2'
  | 'B1'
  | 'B2'
  | 'C1'
  | 'C2';

export type CompletionVariant =
  | 'NOTE'
  | 'SENTENCE'
  | 'SUMMARY';

export type ConversationHostInput = {
  /** Shown to learners instead of HOST1/HOST2 (saved on the draft). */
  name?: string | null | undefined;
  voiceId: string;
};

export type ConversationVoiceoverInput = {
  host1: ConversationHostInput;
  host2: ConversationHostInput;
  localizationId: string;
  /** eleven_v3 (the default) or eleven_v3_conversational. */
  modelId: string;
};

export type CreateResourceInput = {
  body?: unknown;
  cefrLevel?: CefrLevel | null | undefined;
  kind: ResourceKind;
  locale?: string;
  siteId: string;
  slug: string;
  speakerNames?: SpeakerNamesInput | null | undefined;
  summary?: string | null | undefined;
  title: string;
  topicSlugs?: Array<string> | null | undefined;
};

export type GapAnswerInput = {
  gapId: string;
  text: string;
};

export type GradePracticeInput = {
  /** At most 100. */
  answers: Array<PracticeAnswerInput>;
  exerciseSetId: string;
};

export type Judgement =
  | 'FALSE'
  | 'NO'
  | 'NOT_GIVEN'
  | 'TRUE'
  | 'YES';

/** The four parts of a reading lesson. */
export type LessonPart =
  | 'QUESTIONS'
  | 'SCRIPT'
  | 'VOCABULARY'
  | 'VOICEOVER';

export type LexicalEntryKind =
  | 'COLLOCATION'
  | 'IDIOM'
  | 'PHRASAL_VERB'
  | 'PHRASE'
  /** A grammar or sentence pattern, e.g. "If I were you, I'd + verb". Learners add it whole. */
  | 'SENTENCE_PATTERN'
  | 'WORD';

export type LexicalExampleInput = {
  explanation?: string | null | undefined;
  sentence: string;
};

export type LexicalItemApproval = {
  example?: string | null | undefined;
  id: string;
  ieltsTip?: string | null | undefined;
  kind: LexicalItemKind;
  meaning: string;
  synonyms: Array<string>;
};

export type LexicalItemKind =
  | 'COLLOCATION'
  | 'IDIOM'
  | 'KEYWORD'
  /** A paraphrase: other words for the same idea, as IELTS questions reword the passage. */
  | 'PARAPHRASE'
  | 'PHRASAL_VERB'
  /** A sentence structure or grammar pattern. */
  | 'STRUCTURE';

export type LexicalItemStatus =
  /** Checked by an editor: learners see it once the lesson is published. */
  | 'APPROVED'
  /** Explained by the model, waiting for an editor. */
  | 'DRAFT'
  /** Waiting for the local language model to explain it. */
  | 'PENDING';

/**
 * Creates a sense (and its entry, given headword and kind), or edits a sense's draft. Editing a sense with no
 * draft starts a new draft revision; the published one is never changed.
 */
export type ManageLexicalSenseInput = {
  cefrLevel?: CefrLevel | null | undefined;
  definition: string;
  /** For a new sense: its entry, or headword + kind to create one. */
  entryId?: string | null | undefined;
  examples?: Array<LexicalExampleInput>;
  headword?: string | null | undefined;
  kind?: LexicalEntryKind | null | undefined;
  /** Required when editing an existing draft. */
  lockVersion?: number | null | undefined;
  partOfSpeech: string;
  pronunciations?: Array<PronunciationInput>;
  register?: string | null | undefined;
  /** An existing sense to edit. Omit to create one. */
  senseId?: string | null | undefined;
  senseKey: string;
  siteId: string;
  translations?: Array<TranslationInput>;
  usageNote?: string | null | undefined;
};

export type MatchAnswerInput = {
  itemId: string;
  optionId: string;
};

export type MatchingVariant =
  | 'FEATURES'
  | 'HEADINGS'
  | 'INFORMATION'
  | 'SENTENCE_ENDINGS';

/**
 * One answer: optionId (single choice), optionIds (multiple choice), judgement (TFNG, YNNG), matches (matching),
 * gaps (gap fill, completion) or text (short answer).
 */
export type PracticeAnswerInput = {
  gaps?: Array<GapAnswerInput> | null | undefined;
  judgement?: Judgement | null | undefined;
  matches?: Array<MatchAnswerInput> | null | undefined;
  optionId?: string | null | undefined;
  optionIds?: Array<string> | null | undefined;
  questionId: string;
  text?: string | null | undefined;
};

export type PronunciationInput = {
  accent: string;
  ipa: string;
};

export type QuestionSuggestionStatus =
  | 'APPROVED'
  | 'PENDING'
  | 'REJECTED';

export type QuestionType =
  | 'COMPLETION'
  | 'GAP_FILL'
  | 'MATCHING'
  | 'MULTIPLE_CHOICE'
  | 'SHORT_ANSWER'
  | 'SINGLE_CHOICE'
  | 'TRUE_FALSE_NOT_GIVEN'
  | 'YES_NO_NOT_GIVEN';

export type ResourceFilter = {
  cefrLevel?: CefrLevel | null | undefined;
  kind?: ResourceKind | null | undefined;
  /** Defaults to the site's default locale. */
  locale?: string | null | undefined;
  /** Full-text search in titles, summaries and text. */
  search?: string | null | undefined;
  topicSlug?: string | null | undefined;
};

export type ResourceKind =
  | 'ARTICLE'
  | 'LEXICAL_COLLECTION'
  | 'LISTENING'
  | 'READING';

export type RevisionStatus =
  | 'DRAFT'
  | 'IN_REVIEW'
  | 'PUBLISHED'
  | 'SUPERSEDED';

export type SiteRole =
  | 'ADMIN'
  | 'EDITOR'
  | 'OWNER'
  | 'REVIEWER'
  | 'VIEWER';

export type SpeakerNamesInput = {
  host1?: string | null | undefined;
  host2?: string | null | undefined;
};

export type TranslationApproval = {
  id: string;
  /** The text to keep: the drafted one, or the editor's edit. */
  text: string;
};

export type TranslationInput = {
  locale: string;
  text: string;
};

export type TranslationStatus =
  /** Checked by an editor: learners see it once the lesson is published. */
  | 'APPROVED'
  /** Made by the local language model, waiting for an editor. */
  | 'DRAFT';

export type UpdateDraftInput = {
  body?: unknown;
  cefrLevel?: CefrLevel | null | undefined;
  localizationId: string;
  lockVersion: number;
  /** Set to replace the host names; null fields clear a name. */
  speakerNames?: SpeakerNamesInput | null | undefined;
  summary?: string | null | undefined;
  title?: string | null | undefined;
  /** Replaces the draft's topics. */
  topicSlugs?: Array<string> | null | undefined;
};

export type VocabularySuggestionStatus =
  | 'APPROVED'
  | 'PENDING'
  | 'REJECTED';

export type VocabularySuggestionsState =
  | 'DONE'
  /** The worker couldn't finish; ask again. */
  | 'FAILED'
  /** Nothing asked yet for this script (the Suggest button starts it). */
  | 'IDLE'
  /** The worker is looking (with the local language model this can take a few minutes). */
  | 'WORKING';

export type VoiceAccent =
  | 'UK'
  | 'US';

export type VoiceGender =
  | 'FEMALE'
  | 'MALE';

export type VoiceoverMode =
  /** Each HOST1/HOST2 turn is read by its host's voice, like a podcast. */
  | 'CONVERSATION'
  /** One voice reads the whole text. */
  | 'SINGLE';

